import type {SidePatch,Element,ImageRegion} from '../model'
import {T,B,I,C,L,IC,P} from '../primitives'
const patches:Record<string,SidePatch>={}
const W=1280,H=909,pw=W/3
const txt=(x:number,y:number,w:number,h:number,text:string,size=15,e:Partial<Element>={})=>T(x,y,w,h,text,size,{color:'#222',...e})
const ct=(x:number,y:number,w:number,h:number,text:string,size=15,e:Partial<Element>={})=>txt(x,y,w,h,text,size,{align:'center',...e})
const title=(x:number,y:number,w:number,text:string,size=30,color='#222',e:Partial<Element>={})=>ct(x,y,w,size*1.6,text,size,{weight:700,color,...e})
