patch(8,2,[ct(35,114,374,96,'MIRI MUSICAL',52,{font:ser,fontStyle:'italic'}),title(40,451,350,'미리 뮤지컬',34,'#111',{font:ser}),ct(47,514,340,301,'꿈을 향해 나아가는 청춘들의 이야기\n\n음악과 함께 펼쳐지는 특별한 무대,\n당신의 일상에 새로운 감동을 전합니다.\n\n각자의 고민과 꿈을 가진 이들이\n서로를 만나 위로와 용기를 나누며\n함께 성장하는 이야기입니다.\n\n지금, 미리 뮤지컬과 함께\n잊지 못할 순간을 만나보세요.',19,{font:ser,lineHeight:1.7}),B(427,0,426,909,y),title(467,94,346,'시놉시스',37,'#111',{font:ser}),txt(468,204,343,215,'작은 마을에서 시작된 음악의 꿈.\n각자의 사연을 가진 청춘들이 만나\n하나의 무대를 만들어갑니다.\n실패와 갈등을 넘어 서로를 믿으며\n진정한 자신을 찾아가는 여정.\n음악으로 이어지는 청춘의 이야기가\n당신의 마음을 따뜻하게 두드립니다.',19,{font:ser,lineHeight:1.55}),...['1부 | Youth|꿈을 향한 첫걸음, 청춘의 시작','2부 | Music|음악으로 이어지는 마음','3부 | Forever|영원히 기억될 우리의 무대'].flatMap((a,i)=>{const[t,b]=a.split('|').length===3?[a.split('|').slice(0,2).join('|'),a.split('|')[2]]:a.split('|');return[B(427,452+i*152,426,141,gray,{radius:'50% 50% 0 0'}),C(514,488+i*152,252,42,t,25,y,{font:ser,radius:0}),ct(464,540+i*152,349,39,b,18,{font:ser})]}),title(895,92,349,'공연 정보',37,'#111',{font:ser}),B(881,169,370,219,'#fff'),...['요일','공연 시작 시간'].map((t,i)=>ct(888+i*180,174,180,36,t,19,{font:ser})),...rows.flatMap((a,i)=>{const[t,v]=a.split('|');return[ct(888,216+i*40,180,37,t,18,{font:ser}),ct(1068,216+i*40,180,37,v,18,{font:ser}),L(881,211+i*40,370,1,'#444')]}),...['공연 시간|130분 (인터미션 10분)','관람 등급|만 7세 이상','공연장|미리 아트센터 대극장'].flatMap((a,i)=>{const[t,v]=a.split('|');return[txt(914,444+i*65,303,29,t,20,{font:ser}),txt(914,474+i*65,309,34,v,18,{font:ser})]}),txt(914,703,302,38,'주의 사항',24,{font:ser}),txt(914,749,309,105,'공연 시작 후 입장이 제한될 수 있습니다.\n공연 중 사진 및 영상 촬영은 금지됩니다.\n관람 전 휴대전화를 꺼주시기 바랍니다.',16,{font:ser,lineHeight:1.9})],[photo(36,92,377,310)],gray,['시놉시스와 일부 작은 인물 설명은 자연스러운 문장으로 복원했습니다.']);
