patch(12,1,[...templehead(47,'주지 스님 인사말','당신의 무거운 짐,\n여기 내려놓으십시오'),txt(47,221,350,356,'바쁜 일상 속에서 잠시 멈춰 서고 싶은 순간,\n미리사의 문은 언제나 여러분을 향해 열려 있습니다.\n\n천년의 시간을 품은 이 도량은\n수많은 이들의 기도와 정성이 쌓인 곳입니다.\n고요한 숲과 맑은 바람 속에서\n마음의 무거운 짐을 잠시 내려놓으십시오.\n\n부처님의 가르침은 멀리 있지 않습니다.\n서로를 배려하는 마음, 작은 나눔과 감사가\n우리의 일상을 밝히는 등불이 됩니다.\n\n미리사에서의 시간이 여러분에게\n따뜻한 위로와 새로운 힘이 되기를 바랍니다.\n\n늘 건강과 평안이 함께하시기를 기원합니다.',13,{font:ser,lineHeight:1.85}),txt(234,607,163,30,'미리사 주지 미리 스님',14,{font:ser}),...templehead(457,'약도 및 사찰 정보','천년 사찰 미리사는\n당신을 기다립니다'),L(457,210,363,1,'#444'),txt(457,227,363,31,'오시는 길 안내',20,{font:ser}),txt(457,474,363,55,'주소  비즈시 미리구 미리산로 123\n천년 사찰 미리사',14,{font:ser,lineHeight:1.7}),L(457,548,363,1,'#444'),txt(457,566,363,35,'교통편 안내',20,{font:ser}),txt(457,609,363,171,'자가용 이용\n비즈 IC → 미리산 방면 → 미리사 주차장\n\n대중교통 이용\n비즈역에서 101번 버스 탑승\n미리사 입구 정류장 하차 후 도보 10분\n\n문의 전화 012-3456-7890',13,{font:ser,lineHeight:1.75}),txt(508,823,290,56,'미리사 홈페이지에서\n자세한 정보를 확인하실 수 있습니다.',12,{font:ser,lineHeight:1.7}),txt(1200,51,60,31,'미리사',17,{font:ser,color:'#fff'}),txt(1030,92,30,269,'천\n년\n의\n기\n도\n가\n살\n아\n숨\n쉬\n는',14,{font:ser,color:'#fff',lineHeight:1.1}),txt(1073,92,30,231,'제\n일\n도\n량\n기\n도\n성\n취',17,{font:ser,color:'#fff',lineHeight:1.25}),txt(902,624,329,49,'천년 사찰',28,{font:ser,color:'#fff'}),txt(902,670,329,145,'미리사',92,{font:'Do Hyeon',color:'#fff'}),ct(904,862,327,25,'문의 전화 012-3456-7890',14,{font:ser,color:'#fff'})],[photo(0,653,427,256),photo(455,263,363,189),photo(463,825,32,32),{...photo(853,0,427,909),layer:'background'}],'#fff',['주지 스님 인사말의 작은 본문은 자연스러운 사찰 인사말로 복원했습니다.']);
